#!/usr/bin/env bash
# One command per JR編 v6 episode 「渋谷Halloweenには近づくな」 (next/CONTRACT.md; docs/V6.md): v6 opening (pinned opening
# frames + NEW mission beat) + v6 body (first choice → TRUE END → guide → the combined run (reused / re-shot) → GOODBYE end
# card → sources). Configs: web3d/shibuya/series/variants/jr/v6/{_opening,<pair>}.json (generated by tools/v6_configs.mjs),
# page variant=v6/<pair>&opening=v6/_opening.
#   tools/render_v6.sh <pair>          validate → render ONLY the NEW + RE-SHOT pieces (opening mission once, shared; body
#                                      pieces per pair; ≤300-frame resumable segments, one browser session each under the
#                                      box lock) → join (pinned opening ranges + reused ranges + new pieces, ONE re-encode) →
#                                      audio mix (v6 cue sheet) → mux → verify (+ frame accuracy) → contact sheet
#                                      → $OUT/<pair>.mp4 + $OUT/<pair>-contact.jpg (+ $WORK/<pair>/report.json)
#   tools/render_v6.sh all             gate taxi zone alt
#   tools/render_v6.sh check [<pair>]  configs == generator, v6 validator (+ sources), reuse maps, every source located +
#                                      asserted (frames, format, beat edges), pinned opening (no browser)
#   tools/render_v6.sh plan [<pair>]   pieces + segment plan with a time estimate per job; fails if a job would exceed 45 min
#   tools/render_v6.sh stills <pair>|opening T1,T2[,…]|new   preview PNGs at BODY seconds (opening: opening seconds; 'new' =
#                                      every new / re-shot beat) → $WORK/<pair>/stills/ (AGENTS default 8000)
#   tools/render_v6.sh contact <pair>  contact sheet of $OUT/<pair>.mp4, every v6 beat labelled (tools/v6_pipeline.py contact)
# SMOKE=1 tools/render_v6.sh <pair>   plumbing test WITHOUT a browser: NEW pieces not rendered yet = black frames; extraction +
#                                      join + audio + mux + verify + accuracy + contact run for real → $WORK/smoke/<pair>.mp4
# MAX_SEGS=N                           render ≤ N missing segments, then exit 3 (re-run → next): one scheduler job per segment.
# Env: OUT (default /workspace/demos/halloween-escape-series/jr-v6), WORK (default …/logs/ssl-claude-halloween/next/render),
#      SRC (variant renders, read only), COMBINED (combined renders, read only), OPENING_MP4 (pinned opening, 426 f),
#      SEG_FRAMES (≤300), MAX_SEGS, AGENTS, PR, PYBIN, CRF (16), X264_PRESET (medium; SMOKE veryfast), BROWSER_LOCK, SMOKE.
# Job budget (s/frame incl. PNG + encode on the shared 8-CPU box + 8 min start-up per job): card-bg ≈2.9 → a 300-frame card
# segment ≈ 22 min; re-shot street/station beats ≈3–4.5 s/frame → ≤ 300 frames ≈ 23–31 min. `plan` prints every job and
# fails when one would exceed 45 min (then lower SEG_FRAMES).
set -euo pipefail
repo_dir=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/.." && pwd)
cd -- "$repo_dir"
L=${V6_LOGS:-/workspace/projects/logs/ssl-claude-halloween/next}
WORK=${WORK:-$L/render}
SRC=${SRC:-/workspace/projects/logs/ssl-claude-halloween/variants/render}
COMBINED=${COMBINED:-/workspace/projects/logs/ssl-claude-halloween/combined/render}
OPENING_MP4=${OPENING_MP4:-$SRC/opening-dde6ef8ff89d1617/opening.mp4}
if [ -n "${SMOKE:-}" ]; then OUT=${OUT:-$WORK/smoke}; else OUT=${OUT:-/workspace/demos/halloween-escape-series/jr-v6}; fi
SEG_FRAMES=${SEG_FRAMES:-300}; [ "$SEG_FRAMES" -le 300 ] || { echo "SEG_FRAMES must be ≤ 300 (contract)" >&2; exit 2; }
PR=${PR:-1}
CRF=${CRF:-16}
X264_PRESET=${X264_PRESET:-$([ -n "${SMOKE:-}" ] && echo veryfast || echo medium)}
LOCK=${BROWSER_LOCK:-/tmp/ssl-halloween-browser.lock}
PAIRS=(gate taxi zone alt)
OPENING=v6/_opening
EXTRA=(--opening "$OPENING")
[ -n "${AGENTS:-}" ] && EXTRA+=(--agents "$AGENTS")
[ "$PR" != 1 ] && EXTRA+=(--pr "$PR")
mkdir -p "$WORK"
log() { echo "[render_v6 $(date +%T)] $*"; }
frames_in() { [ -s "$1" ] || { echo 0; return; }; ffprobe -v error -select_streams v:0 -count_packets -show_entries stream=nb_read_packets -of csv=p=0 "$1" 2>/dev/null || echo 0; }
cues() { node tools/variant_cues.mjs "$@" --opening "$OPENING"; }
jsonv() { python3 -c "import json,sys;d=json.load(open(sys.argv[1]));print(eval(sys.argv[2],{'d':d}))" "$@"; }
PIPE=(python3 tools/v6_pipeline.py)
valid_pair() { case " ${PAIRS[*]} " in *" $1 "*) ;; *) echo "unknown pair '$1' (${PAIRS[*]})" >&2; exit 2 ;; esac; }

# recorder interpreter (lazy): PYBIN → $WORK/.venv-rec → the variants / combined venvs (read only) → build $WORK/.venv-rec → uv run
REC=()
recorder() { [ ${#REC[@]} -gt 0 ] && return
  local py=''
  for c in "${PYBIN:-}" "$WORK/.venv-rec/bin/python" "$SRC/.venv-rec/bin/python" "$COMBINED/.venv-rec/bin/python"; do
    [ -n "$c" ] && [ -x "$c" ] && "$c" -c 'import playwright,PIL' 2>/dev/null && { py=$c; break; }; done
  if [ -z "$py" ]; then { uv venv --quiet "$WORK/.venv-rec" && uv pip install --quiet --python "$WORK/.venv-rec/bin/python" playwright pillow; } >&2 || rm -rf "$WORK/.venv-rec"
    "$WORK/.venv-rec/bin/python" -c 'import playwright,PIL' 2>/dev/null && py=$WORK/.venv-rec/bin/python; fi
  if [ -n "$py" ]; then REC=("$py" tools/record_variant.py); else REC=(uv run --quiet --no-project --with playwright --with pillow python tools/record_variant.py); fi; }
pil_py() { if python3 -c 'import PIL' 2>/dev/null; then echo python3; else recorder; echo "${REC[0]}"; fi; }

# the shared v6 opening: reuse map + its NEW-piece dir (keyed by the opening config + code)
prepare_opening() { mkdir -p "$WORK/opening"
  node tools/variant_cues.mjs --reuse-map "$OPENING" >"$WORK/opening/map.json"
  OPDIR=$WORK/opening/opening-$(node tools/variant_cues.mjs --opening-key --opening "$OPENING"); mkdir -p "$OPDIR"
  [ "$(frames_in "$OPENING_MP4")" -eq 426 ] || { echo "pinned opening $OPENING_MP4: $(frames_in "$OPENING_MP4")/426 frames" >&2; exit 1; }; }

# prepare <pair>: validation + reuse maps + located sources + cue sheet + timeline in $WORK/<pair>/
prepare() { local pair=$1 w=$WORK/$1 id=v6/$1; mkdir -p "$w"
  cues "$id" --check --quiet || { echo "config $id invalid" >&2; exit 1; }
  prepare_opening; cp "$WORK/opening/map.json" "$w/opening-map.json"
  node tools/variant_cues.mjs --reuse-map "$id" >"$w/map.json"
  "${PIPE[@]}" sources --map "$w/map.json" --opening-map "$w/opening-map.json" --src-root "$SRC" --combined-root "$COMBINED" --opening-mp4 "$OPENING_MP4" --out "$w/sources.json"
  cues "$id" --out "$w/cues.json" --timeline "$w/timeline.json" --quiet
  BODYDIR=$w/body-$(cues --part-key "$id"); mkdir -p "$BODYDIR"; }

# new_pieces <map.json> → lines "f0 f1 beats"
new_pieces() { python3 -c "import json,sys;[print(p['f0'],p['f1'],'+'.join(p['beats'])) for p in json.load(open(sys.argv[1]))['pieces'] if p['mode']=='new']" "$1"; }
# seg_bounds f0 f1 → "a b" lines: ceil(n/SEG_FRAMES) segments of (almost) equal length
seg_bounds() { python3 -c "import math,sys;f0,f1,S=map(int,sys.argv[1:]);n=max(1,math.ceil((f1-f0)/S));b=[f0+round(i*(f1-f0)/n) for i in range(n+1)];[print(b[i],b[i+1]) for i in range(n)]" "$1" "$2" "$SEG_FRAMES"; }

# render_piece <part> <variant> <dir> <f0> <f1> <label>: segments into <dir>/new-f0-f1/, then <dir>/new-f0-f1.mp4
render_piece() { local part=$1 variant=$2 bd=$3 f0=$4 f1=$5 lab=$6 name dir list a b k=0 s got t0
  name=$(printf 'new-%04d-%04d' "$f0" "$f1"); dir=$bd/$name
  if [ "$(frames_in "$bd/$name.mp4")" -eq $((f1-f0)) ]; then log "$part $lab ($f0–$f1) done"; return; fi
  mkdir -p "$dir"; list=$dir/concat.txt; : >"$list"
  while read -r a b; do s=$(printf '%s/seg-%02d' "$dir" "$k")
    if [ "$(frames_in "$s.mp4")" -eq $((b-a)) ] && [ -s "$s.jsonl" ]; then log "$part $lab seg $k ($a–$b) done"
    else
      if [ -n "${MAX_SEGS:-}" ] && [ "${SEGS_DONE:-0}" -ge "$MAX_SEGS" ]; then log "MAX_SEGS=$MAX_SEGS reached; re-run to continue"; exit 3; fi
      SEGS_DONE=$(( ${SEGS_DONE:-0} + 1 )); recorder
      rm -f "$s.mp4" "$s.jsonl"; log "$part $lab seg $k: frames $a–$b → $s.mp4 (waiting for the browser lock)"; t0=$SECONDS
      flock "$LOCK" "${REC[@]}" --variant "$variant" --part "$part" --output "$s.mp4" --log "$s.jsonl" --summary "$s.json" --start-frame "$a" --end-frame "$b" "${EXTRA[@]}" </dev/null 2>&1 \
        | grep --line-buffered -v 'toNonIndexed' | tee "$s.log"
      log "$part $lab seg $k finished in $((SECONDS-t0)) s (incl. lock wait)"; echo "$((SECONDS-t0))" >"$s.wall"
      got=$(frames_in "$s.mp4"); [ "$got" -eq $((b-a)) ] || { echo "$part $lab segment $k incomplete: $got/$((b-a)) frames (re-run to resume)" >&2; exit 1; }
    fi
    echo "file '$s.mp4'" >>"$list"; k=$((k+1)); done < <(seg_bounds "$f0" "$f1")
  ffmpeg -nostdin -hide_banner -loglevel error -y -f concat -safe 0 -i "$list" -c copy -movflags +faststart "$bd/$name.mp4"
  got=$(frames_in "$bd/$name.mp4"); [ "$got" -eq $((f1-f0)) ] || { echo "$bd/$name.mp4: $got/$((f1-f0)) frames" >&2; exit 1; }
  log "$part $lab: $bd/$name.mp4 ($((f1-f0)) frames)"; }

render_pair() { local pair=$1 w=$WORK/$1 v D n f0 f1 lab
  valid_pair "$pair"; prepare "$pair"
  if [ -z "${SMOKE:-}" ]; then
    while read -r f0 f1 lab; do render_piece opening "v6/$pair" "$OPDIR" "$f0" "$f1" "$lab"; done < <(new_pieces "$w/opening-map.json")
    while read -r f0 f1 lab; do render_piece body "v6/$pair" "$BODYDIR" "$f0" "$f1" "$lab"; done < <(new_pieces "$w/map.json")
  else log "SMOKE: NEW pieces not rendered yet → black frames; output → $OUT"; w=$w/smoke; mkdir -p "$w"; cp "$WORK/$pair"/{map,opening-map,sources,cues,timeline}.json "$w/"; fi
  mkdir -p "$OUT"; v=$OUT/$pair.mp4
  n=$(jsonv "$w/timeline.json" "d['frames']"); D=$(jsonv "$w/timeline.json" "d['duration']")
  "${PIPE[@]}" join --map "$w/map.json" --opening-map "$w/opening-map.json" --sources "$w/sources.json" --new-dir "$BODYDIR" --opening-new-dir "$OPDIR" \
    --out "$w/video.mp4" --report "$w/join.json" --crf "$CRF" --preset "$X264_PRESET" ${SMOKE:+--smoke}
  tools/audio/run.sh mix --cues "$w/cues.json" --duration "$D" --out "$w/mix.wav" --report "$w/mix.json" --strict --strict-lint
  tools/audio/mux.sh "$w/video.mp4" "$w/mix.wav" "$v"
  verify_pair "$pair" "$w" "$v" "$n"
  "$(pil_py)" tools/v6_pipeline.py contact --video "$v" --timeline "$w/timeline.json" --out "$OUT/$pair-contact.jpg" >/dev/null && log "contact sheet $OUT/$pair-contact.jpg"
  log "$pair done: $v"; }

verify_pair() { local pair=$1 w=$2 v=$3 n=$4 rc=0 segs
  ffmpeg -hide_banner -nostats -i "$v" -vn -af ebur128=peak=true:framelog=quiet -f null - 2>"$w/ebur128.txt" || true
  "${PIPE[@]}" accuracy --video "$v" --join "$w/join.json" --out "$w/accuracy.json" || rc=1
  segs=$w/segments.json
  python3 - "$OPDIR" "$BODYDIR" "$segs" <<'EOF'
import json,sys,glob,os
out=[]
for d in sys.argv[1:3]:
    for f in sorted(glob.glob(os.path.join(d,'new-*','seg-*.json'))):
        s=json.load(open(f));w=f[:-5]+'.wall'
        out.append({k:s.get(k) for k in ('output','frames','wall_s','ms_per_frame','soft')}|({'job_wall_s':int(open(w).read())} if os.path.exists(w) else {}))
json.dump(out,open(sys.argv[3],'w'),indent=1)
EOF
  "${PIPE[@]}" verify --video "$v" --frames "$n" --ebur "$w/ebur128.txt" --out "$w/report.json" \
    --extra "pair=\"$pair\"" --extra "smoke=$([ -n "${SMOKE:-}" ] && echo true || echo false)" --extra "opening=\"$OPENING_MP4\"" \
    --extra "map=$w/map.json" --extra "opening_map=$w/opening-map.json" --extra "sources=$w/sources.json" --extra "join=$w/join.json" \
    --extra "accuracy=$w/accuracy.json" --extra "segments=$segs" --extra "mix=$w/mix.json" || rc=1
  [ $rc -eq 0 ] || { echo "verify failed for $pair (see $w/report.json)" >&2; exit 1; }
  log "verified $v → $w/report.json"; }

plan_pair() { local pair=$1 w=$WORK/$1; valid_pair "$pair"; prepare "$pair" >/dev/null
  python3 - "$w/opening-map.json" "$w/map.json" "$w/timeline.json" "$SEG_FRAMES" "$OPDIR" "$BODYDIR" <<'EOF'
import json,sys,os,math
om=json.load(open(sys.argv[1]));m=json.load(open(sys.argv[2]));tl=json.load(open(sys.argv[3]));S=int(sys.argv[4]);od,bd=sys.argv[5:7]
# s/frame (wall, incl. PNG + encode) per shot key (render_variant.sh / render_combined.sh plan) + WARM s per job
MS={'op-flythrough':2.9,'topdown':2.9,'aerial':4.4,'eye-walk':3.0,'gate-queue':3.6,'gate-newsouth':2.6,'zone-edge':3.6,'detour':3.2,'routemap':2.4,
    'alt-platform':2.8,'taxi-west':3.2,'taxi-sakura':3.2,'interior':4.5,'card-bg':2.9,'caught-pov':3.6,'black':.6,'continue-bg':2.9,'kaiju-skyline':4.4}
WARM=480;CAP=45*60;worst=0;total=0;jobs=0
print(f"{m['id']}: opening {om['frames']} f + body {m['frames']} f = {tl['frames']} frames, {tl['duration']:.2f} s")
for name,mp,d in (('opening',om,od),('body',m,bd)):
    beats=mp['beats'];cost=lambda f:next((MS.get(b['shot'],4.5) for b in beats if b['f0']<=f<b['f1']),4.5)
    for p in mp['pieces']:
        lab='+'.join(p['beats'])
        if p['mode']=='reuse': print(f"  {name:7s} reuse {p['f0']:4d}–{p['f1']:4d} ({p['frames']:3d} f) {lab:44s} ← {p['src']['variant']} [{p['src']['f0']}–{p['src']['f1']})");continue
        n=max(1,math.ceil(p['frames']/S));b=[p['f0']+round(i*p['frames']/n) for i in range(n+1)];segs=[]
        for a,c in zip(b,b[1:]):
            sec=WARM+sum(cost(f) for f in range(a,c));worst=max(worst,sec);total+=sec;jobs+=1;segs.append(f'{a}-{c} ~{sec/60:.0f} min')
        rs=[x['id'] for x in beats if x['mode']=='new' and x['origin'] and p['f0']<=x['f0']<p['f1']]
        done=os.path.exists(os.path.join(d,f"new-{p['f0']:04d}-{p['f1']:04d}.mp4"))
        print(f"  {name:7s} NEW   {p['f0']:4d}–{p['f1']:4d} ({p['frames']:3d} f) {lab:44s} → {' | '.join(segs)}{'  re-shot: '+','.join(rs) if rs else ''}{'  [rendered]' if done else ''}")
print(f"  {jobs} jobs · render total ~{total/60:.0f} min (opening shared by all pairs) · worst job ~{worst/60:.0f} min (cap 45 min):",'OK' if worst<=CAP else 'TOO LONG -> lower SEG_FRAMES')
sys.exit(0 if worst<=CAP else 1)
EOF
}

stills_pair() { local pair=$1 times=$2 part=body variant w
  if [ "$pair" = opening ]; then part=opening; variant=v6/gate; w=$WORK/opening; prepare_opening; [ "$times" = new ] && times=$(python3 -c "
import json,sys;m=json.load(open(sys.argv[1]));print(','.join(str(round(b['f0']/30+x,3)) for b in m['beats'] if b['mode']=='new' for x in (.4,1.2,3.2)))" "$w/map.json")
  else valid_pair "$pair"; variant=v6/$pair; w=$WORK/$pair; prepare "$pair" >/dev/null
    if [ "$times" = new ]; then times=$(python3 -c "
import json,sys;m=json.load(open(sys.argv[1]));t=[]
K={'first-choice':[1.6,4.2],'true-end':[.6,3.2],'guide':[1.5],'goodbye':[.5,2.5,7.6],'sources':[1.8],'caught':[.5,1.8],'over-stamp':[1.0],'continue':[.6,2.7],'kaiju':[1.0,2.6],'clear-result':[.5,2.4],'clear-stamp':[1.0]}
for b in m['beats']:
  if b['mode']!='new':continue
  for x in K.get(b['id'],[b['frames']/30*.3,b['frames']/30*.75]): t.append(round(b['f0']/30+x,3))
print(','.join(map(str,t)))" "$w/map.json"); fi; fi
  recorder; mkdir -p "$w/stills"
  log "stills $pair ($part) at $times (waiting for the browser lock)"
  AG=(); [ -z "${AGENTS:-}" ] && AG=(--agents 8000)
  flock "$LOCK" "${REC[@]}" --variant "$variant" --part "$part" --stills "$w/stills" --stills-at "$times" "${EXTRA[@]}" "${AG[@]}" 2>&1 | grep --line-buffered -v toNonIndexed
  echo "$w/stills"; }

check_all() { local rc=0 p
  node tools/v6_configs.mjs --check || { echo "v6 configs differ from tools/v6_configs.mjs (run: node tools/v6_configs.mjs --write)" >&2; rc=1; }
  node tools/combined_configs.mjs --check >/dev/null || { echo "combined configs differ from tools/combined_configs.mjs (the v6 copies come from them)" >&2; rc=1; }
  node tools/variant_cues.mjs --validate-v6 --opening "$OPENING" >"$WORK/validate-v6.json" || rc=1
  python3 -c "
import json,sys;d=json.load(open(sys.argv[1]));o=d['opening']
print(f\"v6 opening: {'OK' if o['ok'] else 'INVALID'}\"+''.join(f'\n  error: {e}' for e in o['errors'])+''.join(f'\n  warning: {e}' for e in o['warnings']))
for k,v in d['v6'].items(): print(f\"{k}: {'OK' if v['ok'] else 'INVALID'} · {v['duration']} s · {v['frames']} frames\"+''.join(f'\n  error: {e}' for e in v['errors'])+''.join(f'\n  warning: {e}' for e in v['warnings']))" "$WORK/validate-v6.json"
  prepare_opening || rc=1; echo "pinned opening: $OPENING_MP4 (426 frames) · v6 opening dir $OPDIR"
  for p in "${@:-${PAIRS[@]}}"; do valid_pair "$p"; mkdir -p "$WORK/$p"; cp "$WORK/opening/map.json" "$WORK/$p/opening-map.json"
    node tools/variant_cues.mjs --reuse-map "v6/$p" >"$WORK/$p/map.json" && "${PIPE[@]}" sources --map "$WORK/$p/map.json" --opening-map "$WORK/$p/opening-map.json" \
      --src-root "$SRC" --combined-root "$COMBINED" --opening-mp4 "$OPENING_MP4" --out "$WORK/$p/sources.json" || rc=1; done
  [ $rc -eq 0 ] && echo "check OK" || echo "check FAILED" >&2
  return $rc; }

case "${1:-}" in
  ''|-h|--help) awk 'NR>1 && /^#/{print;next} NR>1{exit}' "$0"; exit 2 ;;
  all) for p in "${PAIRS[@]}"; do render_pair "$p"; done ;;
  check) shift; check_all "$@" ;;
  plan) shift; rc=0; for p in "${@:-${PAIRS[@]}}"; do plan_pair "$p" || rc=1; done; exit $rc ;;
  stills) [ $# -ge 3 ] || { echo "usage: $0 stills <pair>|opening T1,T2|new" >&2; exit 2; }; stills_pair "$2" "$3" ;;
  contact) valid_pair "${2:-}"; w=$WORK/$2; [ -n "${SMOKE:-}" ] && w=$w/smoke; [ -f "$w/timeline.json" ] || { mkdir -p "$w"; cues "v6/$2" --timeline "$w/timeline.json" --quiet; }
           "$(pil_py)" tools/v6_pipeline.py contact --video "$OUT/$2.mp4" --timeline "$w/timeline.json" --out "$OUT/$2-contact.jpg" ;;
  *) render_pair "$1" ;;
esac
